import React, { useState } from 'react';
import { GoogleOAuthProvider, GoogleLogin } from '@react-oauth/google';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';

const CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

function Dashboard({ user, onLogout }) {
  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        bgcolor: '#111',
      }}
    >
      <img src={user.picture} alt="Profile" style={{ borderRadius: '50%', width: 100, marginBottom: 16 }} />
      <Typography variant="h4" sx={{ color: '#00ff88', mb: 2 }}>
        {user.name}
      </Typography>
      <Typography variant="body1" sx={{ color: '#fff', mb: 4 }}>
        {user.email}
      </Typography>
      <Button variant="contained" color="success" onClick={onLogout} sx={{ bgcolor: '#00ff88', color: '#111', fontWeight: 'bold' }}>
        Logout
      </Button>
    </Box>
  );
}

function App() {
  const [user, setUser] = useState(null);

  const onSuccess = (credentialResponse) => {
    // credentialResponse.credential is the JWT from Google
    // Aap isko backend ko bhej sakte hain
    setUser({ token: credentialResponse.credential });
    alert('Login Success! (Demo)');
  };

  const onError = () => {
    alert('Login Failed!');
  };

  const handleLogout = () => {
    localStorage.removeItem('hubbox_token');
    localStorage.removeItem('hubbox_user');
    setUser(null);
  };

  if (!user) {
    return (
      <GoogleOAuthProvider clientId={CLIENT_ID}>
        <Box
          sx={{
            minHeight: '100vh',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            bgcolor: '#111',
          }}
        >
          <Typography variant="h3" sx={{ color: '#00ff88', mb: 4, fontWeight: 'bold', letterSpacing: 2 }}>
            Welcome to Hub Box
          </Typography>
          <GoogleLogin
            onSuccess={onSuccess}
            onError={onError}
            theme="filled_black"
            width="300"
            text="signin_with"
            shape="pill"
          />
        </Box>
      </GoogleOAuthProvider>
    );
  }

  return <Dashboard user={user} onLogout={handleLogout} />;
}

export default App;
